// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 질문하기 (20번)" (e6170958775841a6a23f9d2f0783ef12).
import "./Ask.css";
import { useEffect, useState, type FormEvent, type KeyboardEvent } from "react";
import { useNavigate } from "react-router-dom";
import { getErrorMessage, getFieldErrors } from "../api/client";
import { CATEGORIES, QUESTION_RULES as RULES, createQuestion } from "../api/question";
import { useAuth } from "../hooks/useAuth";

// Page-local styles from the Stitch <head>; mounted only while this page is shown.
const css =
  "body {\n      font-family: 'Noto Sans KR', sans-serif;\n      background-color: #FAFAFA;\n      color: #111827;\n    }\n    .font-mono-code {\n      font-family: 'JetBrains Mono', monospace;\n    }";

type Field = "title" | "content" | "categoryId" | "tags";

// 서버와 같게 이모지 등도 1자로 센다.
const charLength = (value: string) => [...value].length;

// 서버(board.controller.js)와 같은 규칙으로 먼저 검사한다 (REQ-QUESTION-004).
function validate(title: string, content: string, categoryId: string, tags: string[]) {
  const errors: Partial<Record<Field, string>> = {};
  const titleLength = charLength(title.trim());
  if (titleLength < RULES.titleMin) errors.title = `제목은 ${RULES.titleMin}자 이상 입력해주세요.`;
  else if (titleLength > RULES.titleMax) errors.title = `제목은 ${RULES.titleMax}자 이하로 입력해주세요.`;
  if (charLength(content.trim()) < RULES.contentMin) errors.content = `내용은 ${RULES.contentMin}자 이상 입력해주세요.`;
  else if (charLength(content) > RULES.contentMax)
    errors.content = `내용은 ${RULES.contentMax.toLocaleString()}자 이하로 입력해주세요.`;
  if (categoryId === "") errors.categoryId = "카테고리를 1개 선택해주세요.";
  if (tags.length > RULES.maxTags) errors.tags = `태그는 최대 ${RULES.maxTags}개까지 선택할 수 있습니다.`;
  return errors;
}

function FieldError({ message }: { message?: string }) {
  if (!message) return null;
  return (
    <p className="mt-2 text-xs font-medium text-red-600 flex items-center gap-1" role="alert">
      <svg className="w-3.5 h-3.5 shrink-0" fill="currentColor" viewBox="0 0 20 20">
        <path
          clipRule="evenodd"
          d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z"
          fillRule="evenodd"
        ></path>
      </svg>
      {message}
    </p>
  );
}

export default function Ask() {
  const navigate = useNavigate();
  const { user, initializing } = useAuth();
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [categoryId, setCategoryId] = useState("");
  const [tags, setTags] = useState<string[]>([]);
  const [tagInput, setTagInput] = useState("");
  const [errors, setErrors] = useState<Partial<Record<Field, string>>>({});
  const [formError, setFormError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // 질문 작성은 회원만 할 수 있다. 새로고침 직후 로그인 복구(initializing)가 끝난 뒤 판단한다.
  useEffect(() => {
    if (!initializing && !user) navigate("/login", { replace: true });
  }, [initializing, user, navigate]);

  function clearError(field: Field) {
    setErrors((prev) => ({ ...prev, [field]: undefined }));
    setFormError(null);
  }

  // Enter로 태그 추가. 서버처럼 소문자로 바꾸고 중복은 넣지 않는다. 한글 조합 중 Enter는 무시한다.
  function handleTagKeyDown(e: KeyboardEvent<HTMLInputElement>) {
    if (e.key !== "Enter" || e.nativeEvent.isComposing) return;
    e.preventDefault();
    const tag = tagInput.trim().replace(/^#/, "").toLowerCase();
    if (tag === "") return;
    if (tags.length >= RULES.maxTags && !tags.includes(tag)) {
      setErrors((prev) => ({ ...prev, tags: `태그는 최대 ${RULES.maxTags}개까지 선택할 수 있습니다.` }));
      return;
    }
    if (!tags.includes(tag)) setTags([...tags, tag]);
    setTagInput("");
    clearError("tags");
  }

  function removeTag(tag: string) {
    setTags(tags.filter((t) => t !== tag));
    clearError("tags");
  }

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (submitting) return;
    const found = validate(title, content, categoryId, tags);
    setErrors(found);
    if (Object.keys(found).length > 0) return;

    setSubmitting(true);
    setFormError(null);
    try {
      const { questionId } = await createQuestion({ title: title.trim(), content, categoryId: Number(categoryId), tags });
      navigate(`/questions/${questionId}`); // REQ-QUESTION-001: 등록 후 상세 페이지로 이동
    } catch (err) {
      const fieldErrors = getFieldErrors(err);
      if (fieldErrors.length > 0) {
        setErrors(Object.fromEntries(fieldErrors.map(({ field, reason }) => [field, reason])));
      } else {
        setFormError(getErrorMessage(err));
      }
      setSubmitting(false);
    }
  }

  return (
    <div id="page-ask">
      <style>{css}</style>
      <div
        className="min-h-screen flex flex-col antialiased"
        style={{
          backgroundColor: "rgb(255, 253, 245)",
          backgroundImage: "radial-gradient(rgb(217, 212, 195) 1px, transparent 1px)",
          backgroundSize: "18px 18px",
        }}
      >
        {/* BEGIN: MainHeader */}
        <header className="border-b-[2.5px] border-[#111111] bg-white sticky top-0 z-50">
          <div className="max-w-6xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between gap-4">
            {/* Brand Logo */}

            <div className="flex items-center gap-6">
              <a href="#" className="flex items-center text-xl font-black tracking-tight text-[#111111]">
                <span>Dev</span>
                <span className="bg-[#FFD43B] border-2 border-black px-1.5 py-0.5 rounded text-black font-mono font-bold text-sm ml-1">
                  in_
                </span>
              </a>
            </div>

            {/* Search Input Container */}

            <div className="flex-1 max-w-xl mx-2">
              <div className="relative flex items-center">
                <input
                  className="w-full h-10 px-4 text-sm font-medium border-[2.5px] border-[#111111] rounded-[8px] placeholder-gray-400 focus:outline-none focus:ring-0 focus:border-blue-600 transition-colors shadow-brutal-sm"
                  placeholder="검색어를 입력하세요"
                  type="text"
                />
              </div>
            </div>

            {/* Navigation Actions */}

            <div className="flex items-center gap-3">
              <a
                className="hidden sm:inline-flex items-center justify-center px-3.5 py-1.5 text-sm font-bold text-white border-2 border-black rounded-[8px] bg-[#2563EB] shadow-[2px_2px_0_#111111] hover:translate-x-0.5 hover:translate-y-0.5 hover:shadow-none transition-all"
                href="#"
              >
                질문하기
              </a>
              <button
                className="h-10 px-3.5 text-sm font-bold text-black border-2 border-black rounded-[8px] bg-white shadow-[2px_2px_0_#111111] hover:bg-gray-50 hover:translate-x-0.5 hover:translate-y-0.5 hover:shadow-none transition-all flex items-center gap-1"
                type="button"
              >
                <span>알림</span>
                <span className="bg-red-600 text-white rounded-full text-xs px-1.5 py-0.2 font-bold ml-1">3</span>
              </button>
              <button
                className="h-10 px-3.5 text-sm font-bold text-black border-[2.5px] border-[#111111] rounded-[10px] bg-[#FFD43B] shadow-[3px_3px_0_#111111] hover:translate-x-0.5 hover:translate-y-0.5 hover:shadow-none transition-all flex items-center gap-1"
                type="button"
              >
                <span>닉네임 ▾</span>
              </button>
            </div>
          </div>
        </header>
        {/* END: MainHeader */} {/* BEGIN: MainContent */}
        <main className="flex-1 max-w-5xl w-full mx-auto px-4 sm:px-6 py-8">
          {/* Page Title */}

          <div className="mb-6 flex items-baseline justify-between border-b-2 border-black pb-3">
            <h1 className="text-2xl sm:text-3xl font-black text-gray-900 tracking-tight flex items-center gap-2">
              <span>질문하기</span>{" "}
              <span className="text-xs font-mono font-normal px-2 py-0.5 bg-gray-200 border border-black rounded-none">
                MARKDOWN
              </span>
            </h1>

            <span className="text-xs text-gray-500 font-medium">* 표시는 필수 항목입니다.</span>
          </div>

          {/* Question Form */}

          <form className="space-y-6" id="question-form" noValidate onSubmit={handleSubmit}>
            {formError && (
              <p className="text-sm font-bold text-rose-600" role="alert">
                {formError}
              </p>
            )}

            {/* Title Input Section */}

            <section data-purpose="title-field-group">
              <div className="border-[2.5px] border-[#111111] bg-white shadow-brutal flex flex-col sm:flex-row items-stretch rounded">
                <label
                  className="bg-gray-100 border-b-2 sm:border-b-0 sm:border-r-2 border-black font-bold text-sm px-6 py-3.5 flex items-center shrink-0 w-28"
                  htmlFor="title"
                >
                  {" 제목 "}
                </label>

                <div className="flex-1 flex items-center px-4 py-2 relative">
                  <input
                    className="w-full border-none focus:ring-0 text-sm font-medium p-0 text-gray-900 placeholder-gray-400"
                    id="title"
                    placeholder={`제목을 입력하세요 (${RULES.titleMin}~${RULES.titleMax}자)`}
                    type="text"
                    value={title}
                    onChange={(e) => {
                      setTitle(e.target.value);
                      clearError("title");
                    }}
                  />{" "}
                  <span className="text-xs font-mono text-gray-400 ml-2 whitespace-nowrap" id="title-char-counter">
                    {charLength(title.trim())} / {RULES.titleMax}
                  </span>
                </div>
              </div>

              <FieldError message={errors.title} />
            </section>

            {/* Category Select */}

            <section data-purpose="category-field-group">
              <div className="border-[2.5px] border-[#111111] bg-white shadow-brutal flex flex-col sm:flex-row items-stretch rounded">
                <label
                  className="bg-gray-100 border-b-2 sm:border-b-0 sm:border-r-2 border-black font-bold text-sm px-6 py-3.5 flex items-center shrink-0 w-28"
                  htmlFor="category"
                >
                  카테고리
                </label>
                <div className="flex-1 flex items-center px-4 py-2">
                  <select
                    className="w-full border-none focus:ring-0 text-sm font-medium p-0 text-gray-900 bg-transparent cursor-pointer"
                    id="category"
                    value={categoryId}
                    onChange={(e) => {
                      setCategoryId(e.target.value);
                      clearError("categoryId");
                    }}
                  >
                    <option value="">카테고리를 선택하세요</option>
                    {CATEGORIES.map(({ categoryId: id, name }) => (
                      <option key={id} value={id}>
                        {name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              <FieldError message={errors.categoryId} />
            </section>

            {/* Template Checkbox */}

            <div className="flex items-center" data-purpose="template-toggle">
              <label className="inline-flex items-center gap-2 cursor-pointer select-none border-[2.5px] border-[#111111] bg-white px-3 py-1.5 rounded shadow-brutal-sm hover:bg-gray-50 transition-colors">
                <input
                  defaultChecked
                  className="w-4 h-4 rounded-none border-2 border-black text-blue-600 focus:ring-0 focus:ring-offset-0 cursor-pointer"
                  id="template-checkbox"
                  type="checkbox"
                />{" "}
                <span className="text-xs font-bold text-gray-800">질문 템플릿 사용</span>
              </label>
            </div>

            {/* Markdown Editor Container */}

            <section
              className="border-[2.5px] border-[#111111] bg-white shadow-brutal rounded"
              data-purpose="markdown-editor"
            >
              {/* Editor Toolbar */}

              <div className="border-b-[2.5px] border-[#111111] bg-gray-50 px-3 py-2 flex flex-wrap items-center justify-between gap-2">
                {/* Formatting Buttons */}

                <div className="flex items-center flex-wrap gap-1.5 font-mono">
                  <button
                    className="w-8 h-8 flex items-center justify-center font-bold text-sm border border-black bg-white hover:bg-black hover:text-white transition-colors"
                    title="굵게"
                    type="button"
                  >
                    {" B "}
                  </button>{" "}
                  <button
                    className="w-8 h-8 flex items-center justify-center italic font-bold text-sm border border-black bg-white hover:bg-black hover:text-white transition-colors"
                    title="기울임"
                    type="button"
                  >
                    {" I "}
                  </button>{" "}
                  <button
                    className="px-2.5 h-8 flex items-center justify-center font-bold text-xs border border-black bg-white hover:bg-black hover:text-white transition-colors"
                    title="코드 블록"
                    type="button"
                  >
                    {" 코드 블록 ``` "}
                  </button>{" "}
                  <button
                    className="px-2.5 h-8 flex items-center justify-center text-xs font-medium border border-black bg-white hover:bg-black hover:text-white transition-colors"
                    title="링크 추가"
                    type="button"
                  >
                    {" 링크 "}
                  </button>{" "}
                  <button
                    className="px-2.5 h-8 flex items-center justify-center text-xs font-medium border border-black bg-white hover:bg-black hover:text-white transition-colors"
                    title="이미지 첨부"
                    type="button"
                  >
                    {" 이미지 "}
                  </button>
                </div>

                {/* Write/Preview Toggle Tabs */}

                <div className="flex items-center border border-black">
                  <button className="px-4 py-1 text-xs font-bold bg-black text-white" type="button">
                    {" 작성 "}
                  </button>{" "}
                  <button
                    className="px-4 py-1 text-xs font-bold bg-white text-gray-700 hover:bg-gray-100 transition-colors border-l border-black"
                    type="button"
                  >
                    {" 미리보기 "}
                  </button>
                </div>
              </div>

              {/* Editor Content Area */}

              <div className="p-4">
                <textarea
                  className="w-full p-2 border-0 focus:ring-0 font-mono-code text-sm leading-relaxed text-gray-900 placeholder-gray-400 resize-y"
                  id="editor-textarea"
                  placeholder="질문 내용을 자세하게 작성해주세요..."
                  rows={15}
                  value={content}
                  onChange={(e) => {
                    setContent(e.target.value);
                    clearError("content");
                  }}
                />
              </div>
            </section>
            <FieldError message={errors.content} />
            <section data-purpose="tags-input-group">
              <div className="border-[2.5px] border-[#111111] bg-white shadow-brutal flex flex-col sm:flex-row items-stretch rounded">
                <label
                  className="bg-gray-100 border-b-[2.5px] sm:border-b-0 sm:border-r-[2.5px] border-[#111111] font-bold text-sm px-6 py-3.5 flex items-center shrink-0 w-28"
                  htmlFor="tags"
                >
                  태그
                </label>
                <div className="flex-1 flex flex-wrap items-center gap-2 px-4 py-2">
                  {tags.map((tag) => (
                    <span
                      key={tag}
                      className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-mono font-bold bg-[#FFD43B] border-2 border-black rounded shadow-[1.5px_1.5px_0_#111111]"
                    >
                      {`#${tag} `}
                      <button
                        type="button"
                        className="hover:text-red-600 font-bold ml-1"
                        aria-label={`${tag} 태그 삭제`}
                        onClick={() => removeTag(tag)}
                      >
                        ×
                      </button>
                    </span>
                  ))}
                  <input
                    className="flex-1 min-w-[140px] border-none focus:ring-0 text-sm font-medium p-1 text-gray-900 placeholder-gray-400"
                    id="tags"
                    placeholder={`태그를 입력 후 Enter를 누르세요 (선택, 최대 ${RULES.maxTags}개)`}
                    type="text"
                    value={tagInput}
                    onChange={(e) => setTagInput(e.target.value)}
                    onKeyDown={handleTagKeyDown}
                  />
                </div>
              </div>
              {errors.tags ? (
                <FieldError message={errors.tags} />
              ) : (
                <p className="mt-2 text-xs font-medium text-gray-500">
                  질문과 관련된 기술 스택 태그를 추가할 수 있어요. (선택, 최대 {RULES.maxTags}개)
                </p>
              )}
            </section>
            <div className="flex items-center justify-end gap-3 pt-2">
              <button
                type="button"
                onClick={() => navigate(-1)}
                className="px-5 py-2.5 text-sm font-bold text-black border-[2.5px] border-[#111111] bg-white rounded shadow-brutal-sm hover:bg-gray-100 hover:translate-x-0.5 hover:translate-y-0.5 hover:shadow-none transition-all"
              >
                취소
              </button>
              <button
                type="submit"
                disabled={submitting}
                className="px-6 py-2.5 text-sm font-bold text-white border-[2.5px] border-[#111111] bg-[#2563EB] rounded shadow-brutal hover:translate-x-0.5 hover:translate-y-0.5 hover:shadow-none transition-all disabled:opacity-60 disabled:cursor-not-allowed"
              >
                {submitting ? "등록 중..." : "질문 등록"}
              </button>
            </div>
          </form>
        </main>
      </div>
    </div>
  );
}
